GENERAL = """معلومات عامة عن البرنامج:
- النقاط: كل توليد بالذكاء الاصطناعي (فيديو، صور، صوت، كتابة) يُخصم من النقاط على قدر حجمه، والتكلفة تظهر قبل الضغط على «ولّد».
- الباقات: تجربة مجانية، وبداية، ومحترف، ووكالات. التفاصيل في «باقتي ونقاطي».
- كل ما يُنتج يُحفظ في «مكتبة المحتويات»، والمشاريع غير المكتملة في «قيد العمل».
- عقل العلامة هو أساس كل شيء: كلما اكتمل، كانت الأفكار والنصوص أدق."""


def page_text(key: str) -> str:
    p = PAGES.get(key)
    if not p:
        return ""
    return f"الصفحة الحالية: «{p['name']}»\nما تفعله: {p['what']}\nطريقة الاستخدام:\n" + "\n".join(f"{i + 1}. {s}" for i, s in enumerate(p["how"]))


def messages(key: str, history: list[dict], q: str, brand: str = "") -> list[dict]:
    system = ("أنت مساعد الدعم في برنامج SimsimKit لصناعة المحتوى. أجب بالعربية الفصحى البسيطة، باختصار (من جملتين إلى خمس جمل أو خطوات مرقمة)، "
              "واعتمد فقط على المعلومات التالية. إن لم تعرف الإجابة أو كانت المشكلة عطلًا، فقل ذلك بوضوح واقترح «أرسلها للدعم». "
              "لا تذكر أسماء الشركات المزودة للخدمات.\n\n" + GENERAL + "\n\nكل صفحات البرنامج:\n"
              + "\n".join(f"- {p['name']}: {p['what']}" for p in PAGES.values()) + "\n\n" + page_text(key)
              + (f"\n\nعن علامة العميل باختصار: {brand[:600]}" if brand else ""))
    msgs = [{"role": "system", "content": system}]
    for h in history[-8:]:
        if isinstance(h, dict) and h.get("role") in ("user", "assistant") and str(h.get("text") or "").strip():
            msgs.append({"role": h["role"], "content": str(h["text"])[:1500]})
    msgs.append({"role": "user", "content": q[:1500]})
    return msgs


def mock_reply(key: str, q: str) -> str:
    p = PAGES.get(key) or PAGES["home"]
    return f"«{p['name']}»: {p['what']}\n" + "\n".join(f"{i + 1}. {s}" for i, s in enumerate(p["how"]))
